  ('noor-satin-evening-gown', 'dresses', 'Noor Satin Evening Gown', 'Floor-length satin gown with long sleeves and a soft sheen.', 'A fluid floor-length gown in heavy satin with long sleeves, a high neckline and a hidden back zip. Cut generously for a modest, elegant line that moves beautifully.', 18900, NULL, 14, 4.9, 212, 1, NULL, 'Satin', 'Relaxed', 'Evening', 'Dry clean only', '["Satin","Hidden zip","Fully lined"]', '{"drape":5,"warmth":2,"structure":3}', '[{"label":"XS","price_cents":18900},{"label":"S","price_cents":18900},{"label":"M","price_cents":18900},{"label":"L","price_cents":18900},{"label":"XL","price_cents":20900}]', '[{"label":"Black","value":"#14120F"},{"label":"Midnight","value":"#1F2A44"},{"label":"Bordeaux","value":"#5B1A2E"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"gown","color":"#14120F"}', date('now', '-3 days')),
  ('celeste-pleated-maxi-dress', 'dresses', 'Celeste Pleated Maxi Dress', 'Airy chiffon maxi with fine pleats and a covered neckline.', 'Lightweight chiffon with micro-pleats from the waist, a relaxed fit, wide cuffs and a soft inner lining. Made for warm days, weddings and everything in between.', 12800, NULL, 22, 4.8, 168, 1, NULL, 'Chiffon', 'Flowy', 'Day to evening', 'Machine wash cold, gentle', '["Chiffon","Pleats","Lined"]', '{"drape":5,"warmth":1,"structure":2}', '[{"label":"XS","price_cents":12800},{"label":"S","price_cents":12800},{"label":"M","price_cents":12800},{"label":"L","price_cents":12800},{"label":"XL","price_cents":12800}]', '[{"label":"Champagne","value":"#D8C3A1"},{"label":"Sage","value":"#8A9A7B"},{"label":"Dusty rose","value":"#C9A0A0"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"dress","color":"#D8C3A1"}', date('now', '-12 days')),
  ('amara-embroidered-dress', 'dresses', 'Amara Embroidered Dress', 'Gold-thread embroidery along the yoke and cuffs.', 'A cotton-blend dress with hand-finished gold-thread embroidery at the yoke and cuffs, side pockets and a relaxed A-line shape.', 14600, NULL, 18, 4.8, 121, 0, NULL, 'Cotton blend', 'Relaxed', 'Festive', 'Hand wash cold', '["Cotton blend","Embroidery","Pockets"]', '{"drape":3,"warmth":2,"structure":3}', '[{"label":"XS","price_cents":14600},{"label":"S","price_cents":14600},{"label":"M","price_cents":14600},{"label":"L","price_cents":14600},{"label":"XL","price_cents":14600}]', '[{"label":"Ivory","value":"#F2EADB"},{"label":"Black","value":"#14120F"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"dress","color":"#B8924A"}', date('now', '-21 days')),
  ('sahar-linen-wrap-dress', 'dresses', 'Sahar Linen Wrap Dress', 'Breathable linen midi with an adjustable wrap front.', 'Washed European linen cut into a modest wrap midi with long sleeves and an adjustable waist tie. Gets softer with every wash.', 9800, NULL, 35, 4.7, 143, 0, NULL, 'Linen', 'Wrap', 'Everyday', 'Machine wash 30 degrees', '["Linen","Wrap front","Breathable"]', '{"drape":3,"warmth":2,"structure":3}', '[{"label":"XS","price_cents":9800},{"label":"S","price_cents":9800},{"label":"M","price_cents":9800},{"label":"L","price_cents":9800},{"label":"XL","price_cents":9800}]', '[{"label":"Sage","value":"#8A9A7B"},{"label":"Sand","value":"#D9C6A5"},{"label":"Terracotta","value":"#B5654A"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"dress","color":"#8A9A7B"}', date('now', '-30 days')),
  ('layla-lace-wedding-gown', 'dresses', 'Layla Lace Wedding Gown', 'Ivory lace gown with a modest neckline and a sweeping hem.', 'A bridal gown in soft French-style lace with sheer sleeves over a lined bodice, a modest neckline and a gently flared skirt with a short train.', 32000, NULL, 6, 4.9, 64, 1, NULL, 'Lace', 'Tailored', 'Wedding', 'Dry clean only', '["Lace","Lined bodice","Short train"]', '{"drape":4,"warmth":2,"structure":4}', '[{"label":"XS","price_cents":32000},{"label":"S","price_cents":32000},{"label":"M","price_cents":32000},{"label":"L","price_cents":32000},{"label":"XL","price_cents":35000}]', '[{"label":"Ivory","value":"#F4EDE0"},{"label":"Champagne","value":"#E7D8BC"}]', '["Made to measure on request","Free alterations advice","Ships in 5 working days"]', '{"type":"gown","color":"#F4EDE0"}', date('now', '-39 days')),
  ('rhea-tiered-cotton-dress', 'dresses', 'Rhea Tiered Cotton Dress', 'Easy tiered cotton dress in soft summer prints.', 'A breezy tiered dress in lightweight cotton with a round neckline, long sleeves and a swingy hem. Light enough for the hottest days.', 8400, NULL, 41, 4.6, 97, 0, NULL, 'Cotton', 'Flowy', 'Everyday', 'Machine wash 30 degrees', '["Cotton","Tiered","Light"]', '{"drape":4,"warmth":1,"structure":2}', '[{"label":"XS","price_cents":8400},{"label":"S","price_cents":8400},{"label":"M","price_cents":8400},{"label":"L","price_cents":8400},{"label":"XL","price_cents":8400}]', '[{"label":"Cream","value":"#F2EADB"},{"label":"Navy","value":"#1F2A44"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"dress","color":"#E8DCC4"}', date('now', '-48 days')),
  ('ivy-velvet-party-dress', 'dresses', 'Ivy Velvet Party Dress', 'Rich stretch velvet with a flattering modest cut.', 'Soft stretch velvet in a deep jewel tone with long sleeves, a gentle waist and a below-calf hem. A winter party favourite.', 11200, NULL, 0, 4.7, 58, 0, NULL, 'Velvet', 'Tailored', 'Evening', 'Dry clean only', '["Velvet","Stretch","Lined"]', '{"drape":3,"warmth":4,"structure":4}', '[{"label":"XS","price_cents":11200},{"label":"S","price_cents":11200},{"label":"M","price_cents":11200},{"label":"L","price_cents":11200},{"label":"XL","price_cents":11200}]', '[{"label":"Bordeaux","value":"#5B1A2E"},{"label":"Emerald","value":"#14543F"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"dress","color":"#5B1A2E"}', date('now', '-57 days')),
  ('aziza-open-front-abaya', 'abayas', 'Aziza Open-Front Abaya', 'Classic black crepe abaya with a clean open front.', 'A wardrobe staple in matte crepe: open front with hidden snaps, wide sleeves with a subtle cuff and a straight, floor-skimming line.', 13800, NULL, 26, 4.9, 301, 1, NULL, 'Crepe', 'Open front', 'Everyday', 'Machine wash cold, hang dry', '["Crepe","Hidden snaps","Wide sleeves"]', '{"drape":4,"warmth":2,"structure":3}', '[{"label":"XS","price_cents":13800},{"label":"S","price_cents":13800},{"label":"M","price_cents":13800},{"label":"L","price_cents":13800},{"label":"XL","price_cents":13800}]', '[{"label":"Black","value":"#14120F"},{"label":"Charcoal","value":"#3A3F4A"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"abaya","color":"#14120F"}', date('now', '-66 days')),
  ('medina-embroidered-abaya', 'abayas', 'Medina Embroidered Abaya', 'Black abaya with gold embroidery down the front and sleeves.', 'Heavier crepe with tonal and gold-thread embroidery down the front panels and sleeve edges. Made for Eid, dinners and occasions.', 17600, NULL, 12, 4.9, 187, 1, NULL, 'Crepe', 'Open front', 'Festive', 'Dry clean recommended', '["Crepe","Gold thread","Lined sleeves"]', '{"drape":4,"warmth":3,"structure":3}', '[{"label":"XS","price_cents":17600},{"label":"S","price_cents":17600},{"label":"M","price_cents":17600},{"label":"L","price_cents":17600},{"label":"XL","price_cents":17600}]', '[{"label":"Black and gold","value":"#14120F"},{"label":"Black and silver","value":"#2A2A2E"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"abaya","color":"#14120F"}', date('now', '-75 days')),
  ('safiya-linen-kaftan', 'abayas', 'Safiya Linen Kaftan', 'Relaxed linen kaftan with side slits and a drawstring.', 'An easy, breathable kaftan in washed linen with a drawstring waist, side slits and roomy sleeves. Wear it open over a dress or closed on its own.', 9200, NULL, 30, 4.7, 112, 0, NULL, 'Linen', 'Relaxed', 'Everyday', 'Machine wash 30 degrees', '["Linen","Drawstring","Side slits"]', '{"drape":4,"warmth":1,"structure":2}', '[{"label":"XS","price_cents":9200},{"label":"S","price_cents":9200},{"label":"M","price_cents":9200},{"label":"L","price_cents":9200},{"label":"XL","price_cents":9200}]', '[{"label":"Sand","value":"#D9C6A5"},{"label":"Olive","value":"#6B7048"},{"label":"White","value":"#F7F3EA"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"abaya","color":"#D9C6A5"}', date('now', '-84 days')),
