  ('silk-chiffon-hijab', 'scarves', 'Silk Chiffon Hijab', 'Featherlight chiffon hijab with a soft matte finish.', 'A generous 180 x 70 cm hijab in featherlight chiffon with hand-rolled edges. Drapes cleanly, stays put and does not fray.', 2800, NULL, 120, 4.8, 402, 1, NULL, 'Chiffon', 'Rectangle', 'Everyday', 'Hand wash cold', '["Chiffon","Hand-rolled edges","180 x 70 cm"]', '{"drape":5,"warmth":1,"structure":1}', NULL, '[{"label":"Ivory","value":"#F2EADB"},{"label":"Black","value":"#14120F"},{"label":"Sage","value":"#8A9A7B"},{"label":"Dusty rose","value":"#C9A0A0"}]', '["180 x 70 cm","Hand-rolled edges"]', '{"type":"hijab","color":"#F2EADB"}', date('now', '-12 days')),
  ('jersey-instant-hijab', 'scarves', 'Instant Jersey Hijab', 'Pull-on jersey hijab that needs no pins.', 'Stretch cotton jersey with a built-in inner cap and a soft neckline. Pull on and go in under ten seconds.', 1800, NULL, 200, 4.7, 355, 0, NULL, 'Jersey', 'Pull-on', 'Everyday', 'Machine wash 30 degrees', '["Jersey","No pins","Inner cap"]', '{"drape":3,"warmth":3,"structure":2}', NULL, '[{"label":"Black","value":"#14120F"},{"label":"Stone","value":"#B8AC98"},{"label":"Navy","value":"#1F2A44"}]', '["Pull-on design"]', '{"type":"hijab","color":"#B8AC98"}', date('now', '-21 days')),
  ('satin-silk-scarf', 'scarves', 'Satin Silk Scarf', 'Printed satin scarf for hair, neck or bag.', 'A square satin scarf with a subtle gold-and-ink print. Wear it as a headscarf, neck tie or bag charm.', 4200, NULL, 48, 4.6, 76, 0, NULL, 'Satin', 'Square', 'Accessory', 'Hand wash cold', '["Satin","Printed","90 x 90 cm"]', '{"drape":4,"warmth":1,"structure":2}', NULL, '[{"label":"Gold","value":"#B8924A"},{"label":"Ink","value":"#1F2A44"}]', '["90 x 90 cm"]', '{"type":"hijab","color":"#B8924A"}', date('now', '-30 days')),
  ('cotton-undercap-set', 'scarves', 'Cotton Undercap Set', 'Three breathable undercaps in soft cotton.', 'A set of three soft cotton undercaps with a non-slip band, in neutral shades that sit comfortably under any hijab.', 2200, NULL, 90, 4.7, 224, 0, NULL, 'Cotton', 'Pull-on', 'Everyday', 'Machine wash 40 degrees', '["Cotton","Non-slip band","Set of 3"]', '{"drape":2,"warmth":2,"structure":2}', NULL, NULL, '["Set of 3"]', '{"type":"hijab","color":"#E8DCC4"}', date('now', '-39 days')),
