  ('black-longline-trench', 'outerwear', 'Black Longline Trench', 'Water-resistant trench with a belted waist.', 'A classic trench in a water-resistant cotton blend with a storm flap, belted waist and a hem that falls below the knee.', 16400, NULL, 17, 4.7, 102, 0, NULL, 'Cotton blend', 'Belted', 'Rainy days', 'Spot clean or dry clean', '["Water resistant","Belted","Storm flap"]', '{"drape":3,"warmth":3,"structure":4}', '[{"label":"XS","price_cents":16400},{"label":"S","price_cents":16400},{"label":"M","price_cents":16400},{"label":"L","price_cents":16400},{"label":"XL","price_cents":16400}]', '[{"label":"Black","value":"#14120F"},{"label":"Stone","value":"#B8AC98"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"coat","color":"#14120F"}', date('now', '-57 days')),
  ('quilted-cover-up', 'outerwear', 'Quilted Cover-Up', 'Light quilted coat for cool evenings.', 'A lightweight quilted coat with a snap front and side pockets that layers over any dress or abaya without bulk.', 9600, NULL, 28, 4.6, 71, 0, NULL, 'Polyester fill', 'Relaxed', 'Cool weather', 'Machine wash cold', '["Quilted","Snap front","Light"]', '{"drape":3,"warmth":4,"structure":3}', '[{"label":"XS","price_cents":9600},{"label":"S","price_cents":9600},{"label":"M","price_cents":9600},{"label":"L","price_cents":9600},{"label":"XL","price_cents":9600}]', '[{"label":"Taupe","value":"#8A7A6A"},{"label":"Black","value":"#14120F"}]', '["Free returns within 14 days","Ships in 2 working days","Fully lined"]', '{"type":"coat","color":"#8A7A6A"}', date('now', '-66 days'));
